\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Stereo analog saturator with five selectable modes: Soft, Even, Clip, Warm, and Odd.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Adds warmth, presence, and character from subtle color to heavier drive.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Features oversampling, filters, tilt EQ, auto-gain, and smooth transitions.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Keywords: saturation, analog, drive, distortion, stereo.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Integrated master monitoring and analysis tool for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Includes:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab True Peak metering with target limits\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab LUFS integrated and short-term metering\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Spectrum analysis\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Phase correlation view\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Useful for metering and monitoring during mastering. Keywords: LUFS, spectrum, phase, true peak, monitoring.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Modular master monitoring and analysis tool for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Slot-based workflow (up to 9 slots per instance).\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Includes:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab True Peak and LUFS metering (Short-Term and Integrated)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Spectrum analyzer (Mid/Side, temporal averaging, smoothing, hold/freeze)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Phase correlation (bar) and multi-band phase\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Stereo goniometer\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Oscilloscope\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Spectrogram\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Monitor control (Dim, Solo Mid/Side, Low/Mid/High focus)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab VU meter\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Keywords: LUFS, true peak, spectrum, spectrogram, phase, stereo, monitor, mastering.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 3-Band Transient Shaper with Transparent Crossovers and up to 8x Oversampling. Features per-band Attack/Sustain, LUFS Auto-Gain, Lookahead Limiter, and Delta Monitoring.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 VCA-style compressor with a "Verti-ish" character.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Features:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab L/R independent thresholds\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Ratio, attack, release, and makeup gain\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Knee control\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Stereo and dual-mono modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Sidechain filters and harmonic saturation\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Suitable for mix bus, mastering, and drum processing. Keywords: compressor, VCA, dynamics, stereo, saturation.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Floop Ess Hunter Taming hiss.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Detects and attenuates sibilance in vocal items by writing Volume envelope points. Features multi-band analysis, adaptive thresholds, and ZCR.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui (ReaTeam Extensions repository), v0.10.2 or newer\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 For full documentation and changelog, please refer to the README file. Keywords: vocal, de-esser, envelope, processing, analysis\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Floop Groove-A-Thor\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Groove Extraction and Injection tool for REAPER.}\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Extract the rhythmic feel (timing and velocity) from any Audio or MIDI source and apply it to any target item (Audio or MIDI) with precision.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Key Features:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Groove Extraction from Audio (transients) or MIDI\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Groove Injection with adjustable Timing, Velocity, and Grid Attraction\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Phase Coherent Mode for multi-track drum phase preservation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Advanced Visualizer with LOCKED (Groove) and LIVE (Selection) modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Procedural Groove Generator (Swing, Push/Pull, Velocity Curve)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Groove Library with Bank management\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Non-destructive workflow with Undo support\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Floop Hunter Framework\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Artifact detection and gain-reduction helper for REAPER (Ess / Plosive / Breath). Requires ReaImGui.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Advanced audio analysis tool for Reaper. Detects the musical Key and tempo (BPM) of selected audio items using Spectral Flux and Chromagram algorithms. Features a dynamic UI that adapts to any Reaper theme.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Per-track notes system for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Allows writing, viewing, and managing notes for each track. Notes are automatically saved and recalled when switching tracks.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 V2.0: Massive update! No more background startup script needed. You can safely remove the old Floop Startup script from your SWS Startup actions if you had it configured.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui (ReaTeam Extensions repository), v0.10.2 or newer\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Dynamically generates a companion JSFX (FloopNoteReader) to display notes in the Track Control Panel.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Keywords: notes, track, text, workflow.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Fast track navigation and search tool for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Provides a floating search bar for quickly locating, selecting, and previewing tracks.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui (ReaTeam Extensions repository), v0.10.2 or newer Keywords: search, navigation, track, workflow.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Windows-only script.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Sheet Reader v2.0\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \u169 ? 2025 2026 Floop-s\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Load and view PDF and image files directly inside Reaper. Uses Poppler for PDF-to-image conversion. First, the script checks if "pdftoppm" is installed. If not, it prompts the user\line to install Poppler automatically. Poppler is downloaded from the official release\line page and extracted to the Reaper resource folder:\line https://github.com/oschwartz10612/poppler-windows/releases/download/v25.12.0-0/Release-25.12.0-0.zip Once installed, the script converts PDF pages into images and displays them in the GUI.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires: reapack.com/repos/cfillion/reaimgui/ReaImGui_{\i .ext >= 0.10.2 reapack.com/repos/reapack/sws/SWS_}.ext keywords: sheet, pdf, image, viewer, score, music\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 A utility script for REAPER to calculate time-based effect parameters.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Calculates compressor release times, reverb decay/predelay, and delay times based on the project BPM or custom values.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Features:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Real-time updates.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Supports standard, dotted, and triplet notes.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Reverb multipliers for Hall, Plate, and Room.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui (ReaTeam Extensions repository), v0.10.2 or newer\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Five-track live looping station for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Designed for live performance with automated track setup, smart auto-looping, and hands-free control.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui (ReaTeam Extensions repository), v0.10.2 or newer\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab SWS Extension (ReaTeam Extensions repository) Keywords: looper, live performance, recording, workflow.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Floop\u8217's REAPER Scripts\par}
{\pard \ql \f0 \sa180 \li0 \fi0 This repository contains JSFX effects and Lua scripts for REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The tools focus on workflow enhancement, audio processing, and music production utilities.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 All content is released as open-source software under the GPLv3 license.\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Repository Structure\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\f1 scripts/} - Lua scripts\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\f1 effects/} - JSFX effects\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Each tool is contained in its own folder and includes:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab source file ({\f1 .lua} or {\f1 .jsfx})\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab dedicated README with usage details\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The repository can be used via ReaPack or manual installation.\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Installation\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 ReaPack (recommended)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Open REAPER\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Go to Extensions \u8594 ? ReaPack \u8594 ? Import Repositories\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Add:\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \f1 https://github.com/floop-s/floops-reaper-scripts/raw/main/index.xml\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Install tools from ReaPack browser\sa180\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Manual installation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Download or clone the repository\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Open REAPER \u8594 ? Options \u8594 ? Show REAPER resource path\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Copy files into:\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\f1 .lua} \u8594 ? Scripts/\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\f1 .jsfx} \u8594 ? Effects/\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Refresh REAPER (Actions List for scripts, F5 for JSFX)\sa180\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Featured Tools\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Workflow & Editing\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Scratchpad - notes attached to tracks\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Sheet Reader - PDFs and images inside REAPER\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Search - track navigation and filtering\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Studio Trainer - instrument practice with adaptive BPM\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop ESS Hunter / Hunter Framework - detection and marking system for sibilance, plosives, and breath events for dialogue editing\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Music Tools\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Groove-A-Thor - groove extraction, transfer, and generation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floopa Station - live looping tool\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Audio Processing\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Chrominator - stereo saturation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Floop Master Control (Modular) - modular metering and analysis system\sa180\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Compatibility\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Primary platform: Windows (tested)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab macOS / Linux: partially supported, not fully tested\sa180\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Support\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The project is maintained in spare time.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Tools are provided as-is. Feedback is welcome but not guaranteed to be addressed.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 If useful, support is appreciated:\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\field{\*\fldinst{HYPERLINK "https://ko-fi.com/floopsreaperscripts"}}{\fldrslt{\ul
{\cf1 [image: https://img.shields.io/badge/Ko--fi-Support%20Development-orange?style=flat-square&logo=ko-fi]\cf0}
}}}
\par}
{\pard \qc \f0 \sa180 \li0 \fi0 \emdash\emdash\emdash\emdash\emdash\par}
